select  *  from t_train_user
where deleted = 0 and train_id = #{trainId} and create_user = #{userId}
limit 1

SELECT tu.id , t.id trainId , t.`name` , t.cover_path coverPath , t.description , t.create_user  createUser, tu.create_time createTime, tu.`status`
from t_train t JOIN t_train_user tu ON t.id = tu.train_id
WHERE t.deleted = 0 and tu.deleted = 0 and tu.create_user = #{userId}
